function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aiLogic || {};

  let currentProducts = [];
  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    // 期間バリデーション（業務ロジック使用）
    if (validateComparisonPeriod) {
      const validation = validateComparisonPeriod(startDate, endDate);
      if (!validation.valid) {
        showError(validation.message);
        return false;
      }
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (!stores) return;

      const select = container.querySelector('#select-store');
      if (!select) return;

      select.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        select.appendChild(option);
      });
    } catch (error) {
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    try {
      const keyword = container.querySelector('#input-search')?.value.trim() || '';
      const categoryId = container.querySelector('#select-category')?.value || '';

      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) return;

      let filteredProducts = products.filter(product => product.有効フラグ);

      if (keyword) {
        filteredProducts = filteredProducts.filter(product => 
          product.商品名.includes(keyword) || 
          product.商品コード.includes(keyword)
        );
      }

      if (categoryId) {
        filteredProducts = filteredProducts.filter(product => 
          product.カテゴリID === categoryId
        );
      }

      currentProducts = filteredProducts;
      displayProducts(filteredProducts);
    } catch (error) {
      showError('商品検索に失敗しました');
    }
  }

  // 商品一覧表示
  function displayProducts(products) {
    const tbody = container.querySelector('#products-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    products.forEach(product => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>
          <input type="checkbox" class="product-checkbox" value="${product.商品ID}">
        </td>
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${product.カテゴリ名 || ''}</td>
        <td>${product.単価 || 0}</td>
        <td>${product.在庫数量 || 0}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // 需要予測実行
  async function executeForecast() {
    if (!validateInputs()) return;

    try {
      const storeId = container.querySelector('#select-store').value;
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;

      // 選択された商品を取得
      const selectedProductIds = Array.from(
        container.querySelectorAll('.product-checkbox:checked')
      ).map(cb => cb.value);

      if (selectedProductIds.length === 0) {
        showError('商品を選択してください');
        return;
      }

      // 業務ロジックを使用して予測実行
      const salesData = await collectSalesData(storeId, startDate, endDate);
      const productSalesData = classifySalesDataByProduct(salesData, selectedProductIds);
      const validProductData = filterValidProductData(productSalesData);

      // 外部要因データ収集
      const weatherData = await collectWeatherData(storeId, startDate, endDate);
      const eventData = await collectEventData(storeId, startDate, endDate);
      const seasonalData = await collectSeasonalData(startDate, endDate);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 履歴比較
      const historicalComparison = compareWithHistoricalData(validProductData, startDate, endDate);

      // 予測結果を生成
      const forecast = generateForecastResult(
        validProductData,
        weatherCorrelation,
        eventCorrelation,
        seasonalCorrelation,
        historicalComparison
      );

      currentForecast = forecast;
      displayForecastResult(forecast);
      showSuccess('需要予測が完了しました');

    } catch (error) {
      showError('需要予測の実行に失敗しました: ' + error.message);
    }
  }

  // 予測結果生成（簡易版）
  function generateForecastResult(salesData, weatherCorr, eventCorr, seasonalCorr, historical) {
    const result = {};

    Object.keys(salesData).forEach(productId => {
      const baseQuantity = salesData[productId].averageQuantity || 0;
      let adjustedQuantity = baseQuantity;

      // 各要因による調整
      if (weatherCorr[productId]) {
        adjustedQuantity *= (1 + weatherCorr[productId].impact);
      }
      if (eventCorr[productId]) {
        adjustedQuantity *= (1 + eventCorr[productId].impact);
      }
      if (seasonalCorr[productId]) {
        adjustedQuantity *= (1 + seasonalCorr[productId].impact);
      }

      result[productId] = {
        predictedQuantity: Math.round(adjustedQuantity),
        confidence: calculateConfidence(weatherCorr[productId], eventCorr[productId], seasonalCorr[productId]),
        factors: {
          weather: weatherCorr[productId]?.impact || 0,
          event: eventCorr[productId]?.impact || 0,
          seasonal: seasonalCorr[productId]?.impact || 0
        }
      };
    });

    return result;
  }

  // 信頼度計算
  function calculateConfidence(weatherCorr, eventCorr, seasonalCorr) {
    let confidence = 0.5; // ベース信頼度

    if (weatherCorr && weatherCorr.correlation > 0.3) confidence += 0.2;
    if (eventCorr && eventCorr.correlation > 0.3) confidence += 0.2;
    if (seasonalCorr && seasonalCorr.correlation > 0.3) confidence += 0.1;

    return Math.min(confidence, 1.0);
  }

  // 予測結果表示
  function displayForecastResult(forecast) {
    const tbody = container.querySelector('#forecast-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    Object.keys(forecast).forEach(productId => {
      const product = currentProducts.find(p => p.商品ID === productId);
      if (!product) return;

      const result = forecast[productId];
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${result.predictedQuantity}</td>
        <td>${(result.confidence * 100).toFixed(1)}%</td>
        <td>
          <input type="number" class="order-quantity" 
                 data-product-id="${productId}" 
                 value="${result.predictedQuantity}" 
                 min="0" step="1">
        </td>
        <td>
          <button class="btn-adjust" data-product-id="${productId}">調整</button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // 調整ボタンのイベントリスナー
    container.querySelectorAll('.btn-adjust').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const productId = e.target.dataset.productId;
        adjustOrderQuantity(productId);
      });
    });
  }

  // 発注量調整
  function adjustOrderQuantity(productId) {
    const input = container.querySelector(`input[data-product-id="${productId}"]`);
    if (!input) return;

    const quantity = parseInt(input.value);
    if (!validateNumber(quantity, '発注量', 0)) return;

    // 調整理由の入力ダイアログ（簡易版）
    const reason = prompt('調整理由を入力してください:');
    if (reason === null) return;

    // 調整履歴を記録
    if (!currentForecast[productId].adjustments) {
      currentForecast[productId].adjustments = [];
    }

    currentForecast[productId].adjustments.push({
      originalQuantity: currentForecast[productId].predictedQuantity,
      adjustedQuantity: quantity,
      reason: reason,
      timestamp: new Date().toISOString()
    });

    currentForecast[productId].finalQuantity = quantity;
    showSuccess('発注量を調整しました');
  }

  // 発注データ保存
  async function saveOrderData() {
    try {
      const storeId = container.querySelector('#select-store').value;
      const targetDate = container.querySelector('#input-start-date').value;

      if (!storeId || !targetDate) {
        showError('店舗と対象日を設定してください');
        return;
      }

      const orderData = [];

      Object.keys(currentForecast).forEach(productId => {
        const forecast = currentForecast[productId];
        const quantity = forecast.finalQuantity || forecast.predictedQuantity;

        if (quantity > 0) {
          orderData.push({
            店舗ID: storeId,
            商品ID: productId,
            発注日: new Date().toISOString().split('T')[0],
            納期: targetDate,
            発注数量: quantity,
            予測数量: forecast.predictedQuantity,
            信頼度: forecast.confidence,
            調整履歴: JSON.stringify(forecast.adjustments || []),
            作成日時: new Date().toISOString()
          });
        }
      });

      if (orderData.length === 0) {
        showError('保存する発注データがありません');
        return;
      }

      // 発注データを保存
      for (const order of orderData) {
        await window.aivicApi.save(5, order); // 発注データテーブル
      }

      showSuccess(`${orderData.length}件の発注データを保存しました`);

    } catch (error) {
      showError('発注データの保存に失敗しました: ' + error.message);
    }
  }

  // 一括調整
  function bulkAdjustQuantities() {
    const factor = parseFloat(prompt('調整係数を入力してください (例: 1.1 = 10%増加):'));
    if (isNaN(factor) || factor <= 0) {
      showError('有効な調整係数を入力してください');
      return;
    }

    container.querySelectorAll('.order-quantity').forEach(input => {
      const currentValue = parseInt(input.value) || 0;
      const newValue = Math.round(currentValue * factor);
      input.value = newValue;

      // 調整履歴を記録
      const productId = input.dataset.productId;
      if (currentForecast[productId]) {
        if (!currentForecast[productId].adjustments) {
          currentForecast[productId].adjustments = [];
        }
        currentForecast[productId].adjustments.push({
          originalQuantity: currentValue,
          adjustedQuantity: newValue,
          reason: `一括調整 (係数: ${factor})`,
          timestamp: new Date().toISOString()
        });
        currentForecast[productId].finalQuantity = newValue;
      }
    });

    showSuccess('一括調整が完了しました');
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#btn-search');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 予測実行ボタン
    const forecastBtn = container.querySelector('#btn-forecast');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#btn-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // 一括調整ボタン
    const bulkAdjustBtn = container.querySelector('#btn-bulk-adjust');
    if (bulkAdjustBtn) {
      bulkAdjustBtn.addEventListener('click', bulkAdjustQuantities);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-products');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', (e) => {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(cb => cb.checked = e.target.checked);
      });
    }

    // 検索フィールドでのEnterキー
    const searchInput = container.querySelector('#input-search');
    if (searchInput) {
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
          searchProducts();
        }
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      setupEventListeners();

      // デフォルト日付設定
      const startDateInput = container.querySelector('#input-start-date');
      const endDateInput = container.querySelector('#input-end-date');

      if (startDateInput && endDateInput) {
        const today = new Date();
        const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);

        startDateInput.value = nextWeek.toISOString().split('T')[0];
        endDateInput.value = new Date(nextWeek.getTime() + 6 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
      }

    } catch (error) {
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
